            List<int> result = new List<int>();

            int u = 0;
            bpm = Mathf.Abs(bpm);
            float interval = 60000f / bpm / (bpm >= 255 ? 1 : 2) / Values.TimingPointDensity;
            int total = (int)((to - from) / interval);
            if ((u ^ 1) >= total)
