1	using System.Collections.Generic;
2	using System.IO;
3	using ArcCreate.Utility.Parser;
4	
5	namespace ArcCreate.ChartFormat
6	{
7	    /// <summary>
8	    /// Object for reading a .aff chart file.
9	    /// </summary>
10	    public partial class AffChartReader : ChartReader
11	    {
12	        /// <summary>
13	        /// Initializes a new instance of the <see cref="AffChartReader"/> class. You should use <see cref="ChartReaderFactory"/> to instantiate instead.
14	        /// </summary>
15	        /// <param name="fileAccess">File access wrapper. You should normally use <see cref="PhysicalFileAccess"/>.</param>
16	        /// <param name="relativeDirectory">The directory relative to the base folder.</param>
17	        /// <param name="fullPath">The absolute path leading to the file.</param>
18	        /// <param name="filename">The file name. Passed as-is from include and fragment aff commands.</param>
19	        public AffChartReader(IFileAccessWrapper fileAccess, string relativeDirectory, string fullPath, string filename)
20	            : base(fileAccess, relativeDirectory, fullPath, filename)
21	        {
22	            TimingPointDensity = 1;
23	            AudioOffset = 0;
24	        }
25	
26	        public override Result<ChartError> ParseLine(string line, string path, int lineNumber)
27	        {
28	            RawEventType type = DetermineType(line);
29	            switch (type)
30	            {
31	                case RawEventType.Timing:
32	                    if (!ParseTiming(line, lineNumber).TryUnwrap(out RawTiming timing, out ChartError e))
33	                    {
34	                        return e;
35	                    }
36	
37	                    Events.Add(timing);
38	                    break;
39	
40	                case RawEventType.Tap:
41	                    if (!ParseTap(line, lineNumber).TryUnwrap(out RawTap tap, out e))
42	                    {
43	                        return e;
44	                    }
45	
46	                    Events.Add(tap);
47	                    break;
48	
49	                case RawEventType.Hold:
50	                    if (!ParseHold(line, lineNumber).TryUnwrap(out RawHold hold, out e))
51	                    {
52	                        return e;
53	                    }
54	
55	                    Events.Add(hold);
56	                    break;
57	
58	                case RawEventType.Arc:
59	                    if (!ParseArc(line, lineNumber).TryUnwrap(out RawArc arc, out e))
60	                    {
61	                        return e;
62	                    }
63	
64	                    Events.Add(arc);
65	                    break;
66	
67	                case RawEventType.Camera:
68	                    if (!ParseCamera(line, lineNumber).TryUnwrap(out RawCamera cam, out e))
69	                    {
70	                        return e;
71	                    }
72	
73	                    Events.Add(cam);
74	                    break;
75	
76	                case RawEventType.SceneControl:
77	                    if (!ParseSceneControl(line, lineNumber).TryUnwrap(out RawSceneControl sc, out e))
78	                    {
79	                        return e;
80	                    }
81	
82	                    Events.Add(sc);
83	                    break;
84	
85	                case RawEventType.TimingGroup:
86	                    TotalTimingGroup++;
87	                    CurrentTimingGroup = TotalTimingGroup - 1;
88	                    if (!ParseTimingGroup(line, lineNumber, Filename).TryUnwrap(out RawTimingGroup tg, out e))
89	                    {
90	                        return e;
91	                    }
92	
93	                    TimingGroups.Add(tg);
94	                    break;
95	
96	                case RawEventType.TimingGroupEnd:
97	                    CurrentTimingGroup = 0;
98	                    break;
99	
100	                case RawEventType.Include:
101	                    if (!ParseInclude(line, lineNumber).TryUnwrap(out string inclPath, out e))
102	                    {
103	                        return e;
104	                    }
105	
106	                    string fullInclPath = SwitchFileName(FullPath, inclPath);
107	
108	                    if (AllIncludes.Contains(fullInclPath))
109	                    {
110	                        return ChartError.Property(
111	                            line,
112	                            lineNumber,
113	                            RawEventType.Include,
114	                            0,
115	                            line.Length,
116	                            ChartError.Kind.IncludeReferencedMultipleTimes);
117	                    }
118	
119	                    if (AllFragments.Contains(fullInclPath))
120	                    {
121	                        return ChartError.Property(
122	                            line,
123	                            lineNumber,
124	                            RawEventType.Fragment,
125	                            0,
126	                            line.Length,
127	                            ChartError.Kind.IncludeAReferencedFragment);
128	                    }
129	
130	                    var includeResult = AddInclude(inclPath);
131	                    if (includeResult.IsError)
132	                    {
133	                        return ChartError.ReferencedFile(line, lineNumber, RawEventType.Include, includeResult.Error);
134	                    }
135	
136	                    break;
137	
138	                case RawEventType.Fragment:
139	                    if (!ParseFragment(line, lineNumber).TryUnwrap(out RawFragment fragment, out e))
140	                    {
141	                        return e;
142	                    }
143	
144	                    string fullFragPath = SwitchFileName(FullPath, fragment.File);
145	
146	                    if (AllIncludes.Contains(fullFragPath))
147	                    {
148	                        return ChartError.Property(
149	                            line,
150	                            lineNumber,
151	                            RawEventType.Fragment,
152	                            0,
153	                            line.Length,
154	                            ChartError.Kind.IncludeReferencedMultipleTimes);
155	                    }
156	
157	                    var fragmentResult = AddFragment(fragment.Timing, fragment.File);
158	                    if (fragmentResult.IsError)
159	                    {
160	                        return ChartError.ReferencedFile(line, lineNumber, RawEventType.Fragment, fragmentResult.Error);
161	                    }
162	
163	                    break;
164	            }
165	
166	            return Result<ChartError>.Ok();
167	        }
168	
169	        public override Result<ChartError> ParseHeaderLine(string line, int lineNumber, string path, out bool endOfHeader)
170	        {
171	            endOfHeader = line == "-";
172	            if (endOfHeader)
173	            {
174	                return Result<ChartError>.Ok();
175	            }
176	
177	            StringParser s = new StringParser(line);
178	            if (!s.ReadString(":").TryUnwrap(out TextSpan<string> headerType, out ParsingError e))
179	            {
180	                return ChartError.Parsing(line, lineNumber, RawEventType.Header, e);
181	            }
182	
183	            switch (headerType)
184	            {
185	                case "AudioOffset":
186	                    if (!s.ReadInt().TryUnwrap(out TextSpan<int> offset, out e))
187	                    {
188	                        return ChartError.Parsing(line, lineNumber, RawEventType.Header, e);
189	                    }
190	
191	                    AudioOffset = offset;
192	                    return Result<ChartError>.Ok();
193	
194	                case "TimingPointDensityFactor":
195	                case "TimingPointsDensityFactor":
196	                    if (!s.ReadFloat().TryUnwrap(out TextSpan<float> density, out e))
197	                    {
198	                        return ChartError.Parsing(line, lineNumber, RawEventType.Header, e);
199	                    }
200	
201	                    TimingPointDensity = density;
202	                    return Result<ChartError>.Ok();
203	            }
204	
205	            return ChartError.Property(line, lineNumber, RawEventType.Header, 0, line.Length, ChartError.Kind.InvalidHeader);
206	        }
207	
208	        public override Result<ChartError> FinalValidity()
209	        {
210	            var b = base.FinalValidity();
211	            if (b.IsError)
212	            {
213	                return b;
214	            }
215	
216	            if (CurrentTimingGroup != 0)
217	            {
218	                return ChartError.Format(
219	                    RawEventType.TimingGroup,
220	                    ChartError.Kind.TimingGroupPairInvalid);
221	            }
222	
223	            return Result<ChartError>.Ok();
224	        }
225	
226	        private RawEventType DetermineType(string line)
227	        {
228	            if (line.StartsWith("("))
229	            {
230	                return RawEventType.Tap;
231	            }
232	            else if (line.StartsWith("timing("))
233	            {
234	                return RawEventType.Timing;
235	            }
236	            else if (line.StartsWith("hold("))
237	            {
238	                return RawEventType.Hold;
239	            }
240	            else if (line.StartsWith("arc("))
241	            {
242	                return RawEventType.Arc;
243	            }
244	            else if (line.StartsWith("camera("))
245	            {
246	                return RawEventType.Camera;
247	            }
248	            else if (line.StartsWith("scenecontrol("))
249	            {
250	                return RawEventType.SceneControl;
251	            }
252	            else if (line.StartsWith("timinggroup("))
253	            {
254	                return RawEventType.TimingGroup;
255	            }
256	            else if (line.StartsWith("include("))
257	            {
258	                return RawEventType.Include;
259	            }
260	            else if (line.StartsWith("fragment("))
261	            {
262	                return RawEventType.Fragment;
263	            }
264	            else if (line.StartsWith("};"))
265	            {
266	                return RawEventType.TimingGroupEnd;
267	            }
268	
269	            return RawEventType.Unknown;
270	        }
271	
272	        private Result<ChartFileErrors> AddInclude(string file)
273	        {
274	            AllIncludes.Add(SwitchFileName(FullPath, file));
275	            Events.Add(new RawInclude()
276	            {
277	                Timing = 0,
278	                Type = RawEventType.Include,
279	                TimingGroup = CurrentTimingGroup,
280	                File = file,
281	            });
282	
283	            ChartReader extReader = ChartReaderFactory.GetReader(FileAccess, FullPath, file);
284	            extReader.BlockReferences(AllIncludes, AllFragments);
285	            Result<ChartFileErrors> parseResult = extReader.Parse();
286	            if (parseResult.IsError)
287	            {
288	                return parseResult.Error;
289	            }
290	
291	            foreach (RawTimingGroup group in extReader.TimingGroups)
292	            {
293	                group.Editable = true;
294	                group.File = Path.Combine(RelativeDirectory, group.File);
295	            }
296	
297	            References.Add(extReader);
298	            return Result<ChartFileErrors>.Ok();
299	        }
300	
301	        private Result<ChartFileErrors> AddFragment(int timing, string file)
302	        {
303	            AllFragments.Add(SwitchFileName(FullPath, file));
304	            Events.Add(new RawFragment()
305	            {
306	                Timing = timing,
307	                Type = RawEventType.Fragment,
308	                TimingGroup = CurrentTimingGroup,
309	                File = file,
310	            });
311	
312	            ChartReader extReader = ChartReaderFactory.GetReader(FileAccess, FullPath, file);
313	            extReader.BlockReferences(AllIncludes, AllFragments);
314	            Result<ChartFileErrors> parseResult = extReader.Parse();
315	            if (parseResult.IsError)
316	            {
317	                return parseResult.Error;
318	            }
319	
320	            foreach (RawTimingGroup group in extReader.TimingGroups)
321	            {
322	                group.Editable = false;
323	                group.File = Path.Combine(RelativeDirectory, group.File);
324	            }
325	
326	            foreach (RawEvent e in extReader.Events)
327	            {
328	                if (!(e is RawTiming && e.Timing == 0))
329	                {
330	                    e.Timing += timing;
331	                }
332	
333	                if (e is RawHold)
334	                {
335	                    (e as RawHold).EndTiming += timing;
336	                }
337	
338	                if (e is RawArc)
339	                {
340	                    (e as RawArc).EndTiming += timing;
341	                }
342	            }
343	
344	            References.Add(extReader);
345	            return Result<ChartFileErrors>.Ok();
346	        }
347	    }
348	}
