// Minimal Unity type stubs for compiling ArcCreate reference code in tests.
// These must match Unity's behavior exactly for L0 tests to be valid.
namespace UnityEngine
{
    public static class Mathf
    {
        public const float PI = 3.14159274f;

        public static float Cos(float f) => MathF.Cos(f);
        public static float Sin(float f) => MathF.Sin(f);
        public static float Pow(float f, float p) => MathF.Pow(f, p);
        public static float Sqrt(float f) => MathF.Sqrt(f);

        public static float Abs(float f) => MathF.Abs(f);
        public static int Abs(int value) => Math.Abs(value);

        public static int RoundToInt(float f) => (int)MathF.Round(f);

        public static float Clamp(float value, float min, float max) => Math.Clamp(value, min, max);
        public static int Clamp(int value, int min, int max) => Math.Clamp(value, min, max);

        public static float Min(float a, float b) => MathF.Min(a, b);
        public static int Min(int a, int b) => Math.Min(a, b);

        public static float Max(float a, float b) => MathF.Max(a, b);
        public static int Max(int a, int b) => Math.Max(a, b);
    }

    public struct Vector2
    {
        public float x, y;

        public Vector2(float x, float y) { this.x = x; this.y = y; }

        public static Vector2 one => new(1, 1);
        public static Vector2 zero => new(0, 0);
    }

    public struct Vector3
    {
        public float x, y, z;

