    [Fact]
    public void ParseTimingGroup()
    {
        var text = "AudioOffset:0\n-\ntiming(0,120.00,4.00);\ntiminggroup(noinput){\n  timing(0,180.00,4.00);\n  (500,1);\n};";
        var chart = AffParser.Parse(text);
        Assert.Equal(2, chart.TimingGroups.Count);
