using BetterArc.Chart;
using BetterArc.Chart.Events;
using Xunit;

namespace BetterArc.Tests.Chart;

public class TimingGroupTests
{
    private static TimingGroup MakeGroup(params (int timing, float bpm, float divisor)[] timings)
    {
        var tg = new TimingGroup();
        foreach (var (timing, bpm, divisor) in timings)
        {
            tg.AddTiming(new TimingEvent { Timing = timing, Bpm = bpm, Divisor = divisor });
        }
        tg.RecalculateFloorPositions();
        return tg;
    }

    [Fact]
    public void SingleTiming_FloorPositionAtZero_IsZero()
    {
        var tg = MakeGroup((0, 120f, 4f));
        Assert.Equal(0.0, tg.GetFloorPosition(0));
    }

    [Fact]
    public void SingleTiming_FloorPositionLinearlyScalesWithBpm()
    {
        var tg = MakeGroup((0, 120f, 4f));
        // FloorPosition = Bpm * (timing - eventTiming) = 120 * 1000 = 120000
        Assert.Equal(120000.0, tg.GetFloorPosition(1000));
    }

    [Fact]
    public void SingleTiming_NegativeBpm()
    {
        var tg = MakeGroup((0, -120f, 4f));
        Assert.Equal(-120000.0, tg.GetFloorPosition(1000));
    }

    [Fact]
    public void TwoTimings_FloorPositionAccumulates()
    {
        // BPM=100 for 0-1000ms, then BPM=200 for 1000+
        var tg = MakeGroup((0, 100f, 4f), (1000, 200f, 4f));

        // At t=0: fp=0
        Assert.Equal(0.0, tg.GetFloorPosition(0));

        // At t=1000: fp = 100 * (1000 - 0) = 100000
        Assert.Equal(100000.0, tg.GetFloorPosition(1000));

        // At t=2000: fp = 100000 + 200 * (2000 - 1000) = 300000
        Assert.Equal(300000.0, tg.GetFloorPosition(2000));
    }

    [Fact]
    public void GetBpm_ReturnsCurrentSegmentBpm()
    {
        var tg = MakeGroup((0, 100f, 4f), (1000, 200f, 4f));
        Assert.Equal(100f, tg.GetBpm(500));
        Assert.Equal(200f, tg.GetBpm(1500));
        Assert.Equal(200f, tg.GetBpm(1000));
    }

    [Fact]
    public void GetDivisor_ReturnsCurrentSegmentDivisor()
    {
        var tg = MakeGroup((0, 100f, 4f), (1000, 200f, 8f));
        Assert.Equal(4f, tg.GetDivisor(500));
        Assert.Equal(8f, tg.GetDivisor(1500));
    }

    [Fact]
    public void GetEventAt_TimingBeforeFirst_ReturnsFirst()
    {
        var tg = MakeGroup((100, 120f, 4f));
        Assert.Equal(100, tg.GetEventAt(0).Timing);
    }

    [Fact]
    public void ThreeTimings_FloorPositionChains()
    {
        var tg = MakeGroup((0, 100f, 4f), (1000, 200f, 4f), (2000, 50f, 4f));

        // 0→1000: 100*1000 = 100000
        // 1000→2000: 200*1000 = 200000
        // Total at 2000: 300000
        Assert.Equal(300000.0, tg.GetFloorPosition(2000));

        // 2000→3000: 50*1000 = 50000
        // Total at 3000: 350000
        Assert.Equal(350000.0, tg.GetFloorPosition(3000));
    }

    [Fact]
    public void IntegrationWithAffParser()
    {
        var chart = AffParser.Parse("AudioOffset:0\n-\ntiming(0,178.00,4.00);\ntiming(5000,200.00,4.00);");
        var tg = new TimingGroup();
        foreach (var t in chart.TimingGroups[0].Timings)
            tg.AddTiming(t);
        tg.RecalculateFloorPositions();

        Assert.Equal(0.0, tg.GetFloorPosition(0));
        Assert.Equal(178f * 5000, tg.GetFloorPosition(5000));
        Assert.Equal(178f * 5000 + 200f * 1000, tg.GetFloorPosition(6000));
    }
}
