```csharp
using BetterArc.Chart.Events;
using BetterArc.Utility;

namespace BetterArc.Chart;

public class TimingGroup
{
    private readonly List<TimingEvent> _timings = new();

    public IReadOnlyList<TimingEvent> Timings => _timings;

    public void AddTiming(TimingEvent timing)
    {
        _timings.Add(timing);
    }

    public void RecalculateFloorPositions()
    {
        _timings.Sort((a, b) => a.Timing.CompareTo(b.Timing));

        double floorPosition = 0;
        for (int i = 0; i < _timings.Count - 1; i++)
        {
            var curr = _timings[i];
            var next = _timings[i + 1];
            curr.FloorPosition = floorPosition;
            floorPosition += (double)curr.Bpm * (next.Timing - curr.Timing);
        }

        _timings[_timings.Count - 1].FloorPosition = floorPosition;
    }

    public TimingEvent GetEventAt(int timing)
    {
        int index = _timings.BisectRight(timing, ev => ev.Timing) - 1;
        index = Math.Max(index, 0);
        return _timings[index];
    }

    public float GetBpm(int timing)
    {
        return GetEventAt(timing).Bpm;
    }

    public float GetDivisor(int timing)
    {
        return GetEventAt(timing).Divisor;
    }

    public double GetFloorPosition(int timing)
    {
        var note = GetEventAt(timing);
        return note.FloorPosition + ((double)note.Bpm * (timing - note.Timing));
    }
}
