using Xunit;
using Ref = ArcCreate.Reference.Easing;
using Impl = BetterArc.Utility.Easing;

namespace BetterArc.Tests.Formula;

public class EasingTests
{
    private static readonly float[] TValues = { 0f, 0.25f, 0.5f, 0.75f, 1f };

    private void AssertAllT(Func<float, float, float, float> refFn, Func<float, float, float, float> implFn)
    {
        foreach (float t in TValues)
        {
            Assert.Equal(refFn(0, 1, t), implFn(0, 1, t));
            Assert.Equal(refFn(-5, 10, t), implFn(-5, 10, t));
        }
    }

    [Fact] public void Linear_MatchesReference() => AssertAllT(Ref.Linear, Impl.Linear);
