namespace BetterArc.Tests.Utility;

public class CollectionExtensionTests
{
    [Fact]
    public void BisectRight_ValueBeforeAll_ReturnsZero()
    {
        var list = new List<int> { 10, 20, 30 };
        Assert.Equal(0, list.BisectRight(5));
    }

    [Fact]
    public void BisectRight_ValueAfterAll_ReturnsCount()
    {
        var list = new List<int> { 10, 20, 30 };
        Assert.Equal(3, list.BisectRight(35));
    }

    [Fact]
    public void BisectRight_ValueAtElement_ReturnsAfter()
    {
        var list = new List<int> { 10, 20, 30 };
        Assert.Equal(2, list.BisectRight(20));
    }

    [Fact]
    public void BisectRight_ValueBetween_ReturnsInsertionPoint()
    {
        var list = new List<int> { 10, 20, 30 };
        Assert.Equal(2, list.BisectRight(25));
    }

    [Fact]
    public void BisectRight_WithProjection_FindsByProperty()
    {
        var list = new List<(int timing, string name)> { (0, "a"), (1000, "b"), (3000, "c") };
        Assert.Equal(2, list.BisectRight(1500, x => x.timing));
