using System.Globalization;
using System.Numerics;
using BetterArc.Chart.Events;
using BetterArc.Gameplay.Data;

namespace BetterArc.Chart;

public class AffChart
{
    public int AudioOffset { get; set; }
    public float TimingPointDensity { get; set; } = 1;
    public List<AffTimingGroup> TimingGroups { get; set; } = new();
}

public class AffTimingGroup
{
    public List<TimingEvent> Timings { get; set; } = new();
    public List<Tap> Taps { get; set; } = new();
    public List<Hold> Holds { get; set; } = new();
    public List<Arc> Arcs { get; set; } = new();
    public List<CameraEvent> Cameras { get; set; } = new();
    public List<ScenecontrolEvent> SceneControls { get; set; } = new();
    public string Properties { get; set; } = "";
}

public static class AffParser
{
    public static AffChart Parse(string text)
    {
        var chart = new AffChart();
        chart.TimingGroups.Add(new AffTimingGroup());

        var lines = text.Split('\n');
        bool headerDone = false;
        int currentGroup = 0;

        foreach (var rawLine in lines)
        {
            var line = rawLine.Trim();
            if (string.IsNullOrEmpty(line)) continue;

            if (!headerDone)
            {
                if (line == "-")
                {
                    headerDone = true;
                    continue;
                }
                ParseHeaderLine(chart, line);
                continue;
            }

            if (line.StartsWith("};"))
            {
                currentGroup = 0;
                continue;
            }

            if (line.StartsWith("timinggroup("))
            {
                var tg = new AffTimingGroup();
                int propStart = "timinggroup(".Length;
                int propEnd = line.IndexOf(')');
                if (propEnd > propStart)
                    tg.Properties = line.Substring(propStart, propEnd - propStart);
                chart.TimingGroups.Add(tg);
                currentGroup = chart.TimingGroups.Count - 1;
                continue;
            }

            var group = chart.TimingGroups[currentGroup];
            ParseEventLine(group, line, currentGroup);
        }

        return chart;
    }

    private static void ParseHeaderLine(AffChart chart, string line)
    {
        int colonIdx = line.IndexOf(':');
        if (colonIdx < 0) return;

        var key = line.Substring(0, colonIdx);
        var value = line.Substring(colonIdx + 1);

        switch (key)
        {
            case "AudioOffset":
                chart.AudioOffset = int.Parse(value, CultureInfo.InvariantCulture);
                break;
            case "TimingPointDensityFactor":
            case "TimingPointsDensityFactor":
                chart.TimingPointDensity = float.Parse(value, CultureInfo.InvariantCulture);
                break;
        }
    }

    private static void ParseEventLine(AffTimingGroup group, string line, int groupIndex)
    {
        if (line.StartsWith("timing("))
            ParseTiming(group, line, groupIndex);
        else if (line.StartsWith("("))
            ParseTap(group, line, groupIndex);
        else if (line.StartsWith("hold("))
            ParseHold(group, line, groupIndex);
        else if (line.StartsWith("arc("))
            ParseArc(group, line, groupIndex);
        else if (line.StartsWith("camera("))
            ParseCamera(group, line, groupIndex);
        else if (line.StartsWith("scenecontrol("))
            ParseSceneControl(group, line, groupIndex);
    }

    private static void ParseTiming(AffTimingGroup group, string line, int groupIndex)
    {
        var inner = ExtractParens(line, "timing(");
        var parts = inner.Split(',');
        group.Timings.Add(new TimingEvent
        {
            Timing = ParseInt(parts[0]),
            Bpm = ParseFloat(parts[1]),
            Divisor = ParseFloat(parts[2]),
            TimingGroup = groupIndex,
        });
    }

    private static void ParseTap(AffTimingGroup group, string line, int groupIndex)
    {
        var inner = line.Substring(1, line.IndexOf(')') - 1);
        var parts = inner.Split(',');
        group.Taps.Add(new Tap
        {
            Timing = ParseInt(parts[0]),
            Lane = ParseFloat(parts[1]),
            TimingGroup = groupIndex,
        });
    }

    private static void ParseHold(AffTimingGroup group, string line, int groupIndex)
    {
        var inner = ExtractParens(line, "hold(");
        var parts = inner.Split(',');
        group.Holds.Add(new Hold
        {
            Timing = ParseInt(parts[0]),
            EndTiming = ParseInt(parts[1]),
            Lane = ParseFloat(parts[2]),
            TimingGroup = groupIndex,
        });
    }

    private static void ParseArc(AffTimingGroup group, string line, int groupIndex)
    {
        int closeParenIdx = line.IndexOf(')');
        var inner = line.Substring("arc(".Length, closeParenIdx - "arc(".Length);
        var parts = inner.Split(',');

        var arc = new Arc
        {
            Timing = ParseInt(parts[0]),
            EndTiming = ParseInt(parts[1]),
            XStart = ParseFloat(parts[2]),
            XEnd = ParseFloat(parts[3]),
            LineType = ParseArcLineType(parts[4]),
            YStart = ParseFloat(parts[5]),
            YEnd = ParseFloat(parts[6]),
            Color = ParseInt(parts[7]),
            Sfx = parts[8].Trim(),
            IsTrace = parts[9].Trim().ToLowerInvariant() == "true",
            TimingGroup = groupIndex,
        };

        int bracketStart = line.IndexOf('[', closeParenIdx);
        if (bracketStart >= 0)
        {
            int bracketEnd = line.LastIndexOf(']');
            if (bracketEnd > bracketStart)
            {
                var arctapSection = line.Substring(bracketStart + 1, bracketEnd - bracketStart - 1);
                var arctapParts = arctapSection.Split(new[] { ")," }, StringSplitOptions.None);
                foreach (var part in arctapParts)
                {
                    var trimmed = part.Trim();
                    if (!trimmed.StartsWith("arctap(")) continue;
                    var atInner = trimmed.Substring("arctap(".Length);
                    atInner = atInner.TrimEnd(')');
                    var atArgs = atInner.Split(',');
                    arc.ArcTaps.Add(new ArcTap
                    {
                        Timing = ParseInt(atArgs[0]),
                        Width = atArgs.Length > 1 ? ParseFloat(atArgs[1]) : 1f,
                        TimingGroup = groupIndex,
                    });
                }
            }
        }

        group.Arcs.Add(arc);
    }

    private static void ParseCamera(AffTimingGroup group, string line, int groupIndex)
    {
        var inner = ExtractParens(line, "camera(");
        var parts = inner.Split(',');
        group.Cameras.Add(new CameraEvent
        {
            Timing = ParseInt(parts[0]),
            Move = new Vector3(ParseFloat(parts[1]), ParseFloat(parts[2]), ParseFloat(parts[3])),
            Rotate = new Vector3(ParseFloat(parts[4]), ParseFloat(parts[5]), ParseFloat(parts[6])),
            CameraType = ParseCameraType(parts[7].Trim()),
            Duration = ParseInt(parts[8]),
            TimingGroup = groupIndex,
        });
    }

    private static void ParseSceneControl(AffTimingGroup group, string line, int groupIndex)
    {
        var inner = ExtractParens(line, "scenecontrol(");
        int firstComma = inner.IndexOf(',');
        if (firstComma < 0) return;

        int timing = ParseInt(inner.Substring(0, firstComma));
        var rest = inner.Substring(firstComma + 1);
        int secondComma = rest.IndexOf(',');

        string typename;
        var args = new List<object>();

        if (secondComma < 0)
        {
            typename = rest.Trim();
        }
        else
        {
            typename = rest.Substring(0, secondComma).Trim();
            var argStr = rest.Substring(secondComma + 1);
            foreach (var arg in argStr.Split(','))
            {
                var trimmed = arg.Trim();
                if (float.TryParse(trimmed, CultureInfo.InvariantCulture, out float fval))
                    args.Add(fval);
                else
                    args.Add(trimmed);
            }
        }

        group.SceneControls.Add(new ScenecontrolEvent
        {
            Timing = timing,
            Typename = typename,
            Arguments = args,
            TimingGroup = groupIndex,
        });
    }

    private static string ExtractParens(string line, string prefix)
    {
        int start = prefix.Length;
        int end = line.IndexOf(')', start);
        return line.Substring(start, end - start);
    }

    private static int ParseInt(string s) => int.Parse(s.Trim(), CultureInfo.InvariantCulture);
    private static float ParseFloat(string s) => float.Parse(s.Trim(), CultureInfo.InvariantCulture);

    private static ArcLineType ParseArcLineType(string s) => s.Trim().ToLowerInvariant() switch
    {
        "b" => ArcLineType.B,
        "s" => ArcLineType.S,
        "si" => ArcLineType.Si,
        "so" => ArcLineType.So,
        "sisi" => ArcLineType.SiSi,
        "siso" => ArcLineType.SiSo,
        "sosi" => ArcLineType.SoSi,
        "soso" => ArcLineType.SoSo,
        _ => ArcLineType.Unknown,
    };

    private static CameraType ParseCameraType(string s) => s.ToLowerInvariant() switch
    {
        "l" => CameraType.L,
        "qi" => CameraType.Qi,
        "qo" => CameraType.Qo,
        "reset" => CameraType.Reset,
        "s" => CameraType.S,
        _ => CameraType.L,
    };
}

