    }

    [Fact]
    public void SingleTiming_FloorPositionLinearlyScalesWithBpm()
    {
        var tg = MakeGroup((0, 120f, 4f));
        Assert.Equal(120000.0, tg.GetFloorPosition(1000));
    }

