namespace BetterArc.Render;

public class TrackRenderer
{
    private readonly GraphicsDevice _device;
    private readonly BasicEffect _effect;
    private readonly VertexPositionColor[] _trackVerts;
    private readonly short[] _trackIndices;
    private readonly VertexPositionColor[] _lineVerts;
    private readonly short[] _lineIndices;

    public TrackRenderer(GraphicsDevice device)
    {
        _device = device;
        _effect = new BasicEffect(device) { VertexColorEnabled = true };
        (_trackVerts, _trackIndices) = GeometryBuilder.CreateTrack();
        (_lineVerts, _lineIndices) = GeometryBuilder.CreateLaneDividers();
    }

    public void Draw(CameraService camera)
    {
