```csharp
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace BetterArc.Render;

public static class GeometryBuilder
{
    public static (VertexPositionColor[] vertices, short[] indices) CreateQuad(
        Vector3 topLeft, Vector3 topRight, Vector3 bottomRight, Vector3 bottomLeft, Color color)
    {
        var vertices = new VertexPositionColor[]
        {
            new(topLeft, color),
            new(topRight, color),
            new(bottomRight, color),
            new(bottomLeft, color),
        };
        var indices = new short[] { 0, 1, 2, 0, 2, 3 };
        return (vertices, indices);
    }

    public static (VertexPositionColor[] vertices, short[] indices) CreateTrack()
    {
        float left = Gameplay.ArcFormula.LaneToWorldX(4);
        float right = Gameplay.ArcFormula.LaneToWorldX(1);
        float far = -Gameplay.Values.TrackLengthForward;
        float near = Gameplay.Values.TrackLengthBackward;
        Color trackColor = new Color(30, 30, 40, 200);

        return CreateQuad(
            new Vector3(left, 0, far),
            new Vector3(right, 0, far),
            new Vector3(right, 0, near),
            new Vector3(left, 0, near),
            trackColor);
    }

    public static (VertexPositionColor[] vertices, short[] indices) CreateLaneDividers()
    {
        var allVerts = new List<VertexPositionColor>();
        var allIndices = new List<short>();
        Color lineColor = new Color(80, 80, 100, 150);
        float width = 0.05f;
        float far = -Gameplay.Values.TrackLengthForward;
        float near = Gameplay.Values.TrackLengthBackward;

        for (int lane = 1; lane <= 4; lane++)
        {
            float x = Gameplay.ArcFormula.LaneToWorldX(lane);
            short offset = (short)allVerts.Count;
            var (v, idx) = CreateQuad(
                new Vector3(x - width, 0.01f, far),
                new Vector3(x + width, 0.01f, far),
                new Vector3(x + width, 0.01f, near),
                new Vector3(x - width, 0.01f, near),
                lineColor);
            allVerts.AddRange(v);
            allIndices.AddRange(idx.Select(i => (short)(i + offset)));
        }

        return (allVerts.ToArray(), allIndices.ToArray());
    }
}
```

