using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace BetterArc.Render;

public static class ScreenshotService
{
    public static void CaptureToFile(
        GraphicsDevice device,
        CameraService camera,
        TrackRenderer track,
        NoteRenderer notes,
        Gameplay.GameplayService gameplay,
        int width, int height,
        string outputPath)
    {
        var renderTarget = new RenderTarget2D(device, width, height,
            false, SurfaceFormat.Color, DepthFormat.Depth24);

        device.SetRenderTarget(renderTarget);
        device.Clear(Color.Black);

        camera.Update((float)width / height);
        track.Draw(camera);
        notes.Draw(camera, gameplay);

        device.SetRenderTarget(null);

        using var stream = File.Create(outputPath);
        renderTarget.SaveAsPng(stream, width, height);
        renderTarget.Dispose();
    }
}
```

