using BetterArc.Gameplay;
using Xunit;

namespace BetterArc.Tests.Gameplay;

public class GameplayServiceTests
{
    private const string SimpleChart = "AudioOffset:0\n-\ntiming(0,120.00,4.00);\n(1000,2);\n(2000,3);\nhold(3000,5000,1);\narc(1000,3000,0.00,1.00,s,1.00,1.00,0,none,true);";

    [Fact]
    public void LoadChart_ParsesSuccessfully()
    {
        var svc = new GameplayService();
        svc.LoadChart(SimpleChart);
        Assert.NotNull(svc.Chart);
        Assert.Equal(120f, svc.Chart!.TimingGroups[0].Timings[0].Bpm);
    }

    [Fact]
    public void GetVisibleTaps_AtTiming1000_ReturnsTapAtLane2()
    {
        var svc = new GameplayService();
        svc.LoadChart(SimpleChart);
        svc.CurrentTiming = 1000;
        var taps = svc.GetVisibleTaps(0).ToList();
        Assert.Contains(taps, t => t.Timing == 1000 && t.Lane == 2f);
    }

    [Fact]
    public void GetFloorPosition_UsesTimingGroup()
    {
        var svc = new GameplayService();
        svc.LoadChart(SimpleChart);
        double fp = svc.GetFloorPosition(0, 1000);
        Assert.Equal(120.0 * 1000, fp);
    }

    [Fact]
    public void GetNoteZ_ForwardNote_IsNegative()
    {
        var svc = new GameplayService();
        svc.LoadChart(SimpleChart);
        svc.CurrentTiming = 0;
        float z = svc.GetNoteZ(0, 1000);
        Assert.True(z < 0, "Forward notes should have negative Z");
    }

    [Fact]
    public void GetVisibleArcs_AtTiming1000_ReturnsArc()
    {
        var svc = new GameplayService();
        svc.LoadChart(SimpleChart);
        svc.CurrentTiming = 1000;
        var arcs = svc.GetVisibleArcs(0).ToList();
        Assert.NotEmpty(arcs);
    }

    [Fact]
    public void GetVisibleHolds_AtTiming3000_ReturnsHold()
    {
        var svc = new GameplayService();
        svc.LoadChart(SimpleChart);
        svc.CurrentTiming = 3000;
        var holds = svc.GetVisibleHolds(0).ToList();
        Assert.NotEmpty(holds);
    }
}

