19	
20	        View = Matrix.CreateLookAt(Position, target, Vector3.Up);
21	        Projection = Matrix.CreatePerspectiveFieldOfView(
22	            MathHelper.ToRadians(60f), aspectRatio, 0.1f, 300f);
