using BetterArc.Render;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Xunit;

namespace BetterArc.Tests.Render;

public class CameraServiceTests
{
    [Fact]
    public void Position_MatchesArcCreate()
    {
        var cam = new CameraService();
        cam.Update(16f / 9f);
        Assert.Equal(0f, cam.Position.X, 3);
        Assert.Equal(9f, cam.Position.Y, 3);
        Assert.Equal(-9f, cam.Position.Z, 3);
    }

    [Fact]
    public void View_IsNotIdentity()
    {
        var cam = new CameraService();
        cam.Update(16f / 9f);
        Assert.NotEqual(Matrix.Identity, cam.View);
    }

    [Fact]
    public void Projection_IsNotIdentity()
    {
        var cam = new CameraService();
        cam.Update(16f / 9f);
        Assert.NotEqual(Matrix.Identity, cam.Projection);
    }

    [Fact]
    public void TrackOrigin_ProjectsToScreenCenter()
    {
        var cam = new CameraService();
        cam.Update(16f / 9f);
        var viewport = new Viewport(0, 0, 1280, 720);
        var screenPos = viewport.Project(Vector3.Zero, cam.Projection, cam.View, Matrix.Identity);
        Assert.InRange(screenPos.X, 500, 780);
        Assert.InRange(screenPos.Y, 200, 600);
    }

    [Fact]
    public void Lane1And4_ProjectSymmetrically()
    {
        var cam = new CameraService();
        cam.Update(16f / 9f);
        var viewport = new Viewport(0, 0, 1280, 720);

        float lane1X = BetterArc.Gameplay.ArcFormula.LaneToWorldX(1);
        float lane4X = BetterArc.Gameplay.ArcFormula.LaneToWorldX(4);

        var screen1 = viewport.Project(new Vector3(lane1X, 0, 0), cam.Projection, cam.View, Matrix.Identity);
        var screen4 = viewport.Project(new Vector3(lane4X, 0, 0), cam.Projection, cam.View, Matrix.Identity);

        float center = 640f;
        Assert.Equal(Math.Abs(screen1.X - center), Math.Abs(screen4.X - center), 1);
    }
}

