namespace BetterArc.Judgment;

public class JudgmentService
{
    public static JudgmentResult Judge(int offset)
    {
        int abs = Math.Abs(offset);
        bool early = offset < 0;

        if (abs <= Values.MaxJudgeWindow)
            return JudgmentResult.Max;
        if (abs <= Values.PerfectJudgeWindow)
            return early ? JudgmentResult.PerfectEarly : JudgmentResult.PerfectLate;
        if (abs <= Values.GoodJudgeWindow)
            return early ? JudgmentResult.GoodEarly : JudgmentResult.GoodLate;

        return early ? JudgmentResult.MissEarly : JudgmentResult.MissLate;
    }

    public static bool IsWithinWindow(int offset)
    {
        return Math.Abs(offset) <= Values.MissJudgeWindow;
    }
}

