namespace BetterArc.Judgment;

public class ScoreService
{
    public const int MaxScore = 10_000_000;
    public const float GoodPenaltyMultiplier = 0.5f;

    private int _noteCount;
    private double _scorePerNote;
    private double _currentScore;

    public int NoteCount => _noteCount;
    public int Score => (int)Math.Round(_currentScore);
    public int MaxCombo { get; private set; }
    public int CurrentCombo { get; private set; }
    public int MaxCount { get; private set; }
    public int PerfectCount { get; private set; }
    public int GoodCount { get; private set; }
    public int MissCount { get; private set; }

    public void SetNoteCount(int noteCount)
    {
        _noteCount = noteCount;
        _scorePerNote = noteCount > 0 ? (double)MaxScore / noteCount : 0;
        Reset();
    }

    public void Reset()
    {
        _currentScore = 0;
        CurrentCombo = 0;
        MaxCombo = 0;
        MaxCount = 0;
        PerfectCount = 0;
        GoodCount = 0;
        MissCount = 0;
    }

    public void ProcessResult(JudgmentResult result)
    {
        if (result.IsMiss())
        {
            MissCount++;
            CurrentCombo = 0;
            return;
        }

        CurrentCombo++;
        if (CurrentCombo > MaxCombo)
            MaxCombo = CurrentCombo;

        if (result.IsMax())
        {
            MaxCount++;
            _currentScore += _scorePerNote + 1;
        }
        else if (result.IsPerfect())
        {
            PerfectCount++;
            _currentScore += _scorePerNote + 1;
        }
        else if (result.IsGood())
        {
            GoodCount++;
            _currentScore += _scorePerNote * GoodPenaltyMultiplier;
        }
    }

    public int TheoreticalMaxScore => MaxScore + _noteCount;
}

