namespace BetterArc.Tests.Judgment;

public class JudgmentServiceTests
{
    [Theory]
    [InlineData(0, JudgmentResult.Max)]
    [InlineData(10, JudgmentResult.Max)]
    [InlineData(-25, JudgmentResult.Max)]
    [InlineData(25, JudgmentResult.Max)]
    [InlineData(26, JudgmentResult.PerfectLate)]
    [InlineData(-26, JudgmentResult.PerfectEarly)]
    [InlineData(50, JudgmentResult.PerfectLate)]
    [InlineData(-50, JudgmentResult.PerfectEarly)]
    [InlineData(51, JudgmentResult.GoodLate)]
    [InlineData(-51, JudgmentResult.GoodEarly)]
    [InlineData(100, JudgmentResult.GoodLate)]
    [InlineData(-100, JudgmentResult.GoodEarly)]
    [InlineData(101, JudgmentResult.MissLate)]
    [InlineData(-101, JudgmentResult.MissEarly)]
    public void Judge_ReturnsCorrectResult(int offset, JudgmentResult expected)
    {
        Assert.Equal(expected, JudgmentService.Judge(offset));
    }

    [Theory]
    [InlineData(0, true)]
    [InlineData(120, true)]
    [InlineData(-120, true)]
    [InlineData(121, false)]
    [InlineData(-121, false)]
    public void IsWithinWindow_MatchesExpected(int offset, bool expected)
    {
        Assert.Equal(expected, JudgmentService.IsWithinWindow(offset));
    }
}

public class ScoreServiceTests
{
    [Fact]
    public void AllMax_GivesMaxPlusNoteCount()
    {
        var score = new ScoreService();
        score.SetNoteCount(100);
        for (int i = 0; i < 100; i++)
            score.ProcessResult(JudgmentResult.Max);

        Assert.Equal(10_000_000 + 100, score.Score);
        Assert.Equal(100, score.MaxCombo);
        Assert.Equal(100, score.MaxCount);
    }

    [Fact]
    public void AllGood_GivesHalfScore()
    {
        var score = new ScoreService();
        score.SetNoteCount(100);
        for (int i = 0; i < 100; i++)
            score.ProcessResult(JudgmentResult.GoodEarly);

        Assert.Equal(5_000_000, score.Score);
        Assert.Equal(100, score.GoodCount);
        Assert.Equal(100, score.MaxCombo);
    }

    [Fact]
    public void Miss_BreaksCombo()
    {
        var score = new ScoreService();
        score.SetNoteCount(10);
        score.ProcessResult(JudgmentResult.Max);
        score.ProcessResult(JudgmentResult.Max);
        Assert.Equal(2, score.CurrentCombo);

        score.ProcessResult(JudgmentResult.MissLate);
        Assert.Equal(0, score.CurrentCombo);
        Assert.Equal(2, score.MaxCombo);
        Assert.Equal(1, score.MissCount);
    }

    [Fact]
    public void Perfect_GivesSameScoreAsMax()
    {
        var score = new ScoreService();
        score.SetNoteCount(10);
        score.ProcessResult(JudgmentResult.PerfectEarly);
        score.ProcessResult(JudgmentResult.Max);

        Assert.Equal(score.Score, (int)Math.Round(2 * (10_000_000.0 / 10 + 1)));
    }

    [Fact]
    public void TheoreticalMaxScore_IsMaxPlusNoteCount()
    {
        var score = new ScoreService();
        score.SetNoteCount(500);
        Assert.Equal(10_000_500, score.TheoreticalMaxScore);
    }
}

