using Microsoft.Xna.Framework.Input;

namespace BetterArc.Input;

public class InputService
{
    private static readonly Keys[] LaneKeys = { Keys.D, Keys.F, Keys.J, Keys.K };

    private KeyboardState _prevState;
    private readonly bool[] _lanePressed = new bool[4];
    private readonly bool[] _laneJustPressed = new bool[4];

    public bool IsLanePressed(int lane) => lane >= 1 && lane <= 4 && _lanePressed[lane - 1];
    public bool IsLaneJustPressed(int lane) => lane >= 1 && lane <= 4 && _laneJustPressed[lane - 1];

    public void Update()
    {
        var state = Keyboard.GetState();
        for (int i = 0; i < 4; i++)
        {
            _lanePressed[i] = state.IsKeyDown(LaneKeys[i]);
            _laneJustPressed[i] = state.IsKeyDown(LaneKeys[i]) && _prevState.IsKeyUp(LaneKeys[i]);
        }
        _prevState = state;
    }

    public IEnumerable<int> GetJustPressedLanes()
    {
        for (int i = 0; i < 4; i++)
            if (_laneJustPressed[i])
                yield return i + 1;
    }
}

