namespace BetterArc.Audio;

public class AudioService
{
    private SoundEffectInstance? _music;
    private bool _playing;
    private int _startDelayMs;
    private DateTime _startTime;

    public int ChartTiming { get; private set; }
    public bool IsPlaying => _playing;

    public void LoadOgg(string path)
    {
        if (!File.Exists(path)) return;
        var effect = SoundEffect.FromFile(path);
        _music = effect.CreateInstance();
    }

    public void Play(int startDelayMs = 2000)
    {
        _startDelayMs = startDelayMs;
        _startTime = DateTime.UtcNow;
        _playing = true;
        _music?.Play();
    }

    public void Stop()
    {
        _playing = false;
        _music?.Stop();
    }

    public void Update()
    {
        if (!_playing) return;
        var elapsed = (DateTime.UtcNow - _startTime).TotalMilliseconds;
        ChartTiming = (int)(elapsed - _startDelayMs);
    }

    public void Seek(int timingMs)
    {
        ChartTiming = timingMs;
    }
}

