using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace BetterArc.Render;

public class TextureService
{
    private readonly Dictionary<string, Texture2D> _textures = new();
    private Texture2D _white = null!;

    public void Initialize(GraphicsDevice device)
    {
        _white = new Texture2D(device, 1, 1);
        _white.SetData(new[] { Color.White });

        string? basePath = FindTextureBasePath();
        if (basePath == null) return;

        TryLoad(device, basePath, "track", "Track/TrackWhite.png");
        TryLoad(device, basePath, "trackDivider", "Track/TrackLaneDivider.png");
        TryLoad(device, basePath, "tap", "Note/Light/TapNoteLight.png");
        TryLoad(device, basePath, "hold", "Note/Light/HoldNoteLight.png");
        TryLoad(device, basePath, "arcBody", "Note/ArcBody.png");
        TryLoad(device, basePath, "arcTap", "Note/Light/ArcTapLight.png");
        TryLoad(device, basePath, "arcCap", "Note/ArcCap.png");
        TryLoad(device, basePath, "shadow", "Note/ArcTapShadow.png");
        TryLoad(device, basePath, "heightIndicator", "Note/HeightIndicator.png");
        TryLoad(device, basePath, "criticalLine", "CriticalLine/TrackCriticalLine.png");
        TryLoad(device, basePath, "beatline", "SingleLine/SingleLineLight.png");
    }

    public Texture2D Get(string name) => _textures.GetValueOrDefault(name, _white);
    public bool Has(string name) => _textures.ContainsKey(name);
    public Texture2D White => _white;

    private void TryLoad(GraphicsDevice device, string basePath, string key, string relativePath)
    {
        string fullPath = Path.Combine(basePath, relativePath);
        if (!File.Exists(fullPath)) return;
        using var stream = File.OpenRead(fullPath);
        _textures[key] = Texture2D.FromStream(device, stream);
    }

    private string? FindTextureBasePath()
    {
        string[] candidates =
        {
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "assets", "extracted", "textures"),
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "re", "ArcCreate", "Assets", "Textures", "Gameplay"),
        };
        foreach (var path in candidates)
        {
            string resolved = Path.GetFullPath(path);
            if (Directory.Exists(resolved)) return resolved;
        }
        return null;
    }
}

