using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using BetterArc.Gameplay;
using BetterArc.Gameplay.Data;

namespace BetterArc.Render;

public class NoteRenderer
{
    private readonly GraphicsDevice _device;
    private readonly BasicEffect _effect;

    private static readonly Color[] ArcColors =
    {
        new Color(0, 200, 255),
        new Color(255, 100, 200),
    };
    private static readonly Color TraceColor = new Color(180, 180, 180, 100);
    private static readonly Color ShadowColor = new Color(0, 0, 0, 120);

    public NoteRenderer(GraphicsDevice device)
    {
        _device = device;
        _effect = new BasicEffect(device)
        {
            VertexColorEnabled = true,
            TextureEnabled = true,
        };
    }

    public void Draw(CameraService camera, GameplayService gameplay, TextureService textures)
    {
        if (gameplay.Chart == null) return;

        _effect.View = camera.View;
        _effect.Projection = camera.Projection;
        _effect.World = Matrix.Identity;

        _device.DepthStencilState = DepthStencilState.Default;
        _device.BlendState = BlendState.AlphaBlend;
        _device.RasterizerState = RasterizerState.CullNone;
        _device.SamplerStates[0] = SamplerState.LinearClamp;

        for (int tg = 0; tg < gameplay.Chart.TimingGroups.Count; tg++)
        {
            DrawArcShadows(gameplay, tg, textures);
            DrawHolds(gameplay, tg, textures);
            DrawTaps(gameplay, tg, textures);
            DrawArcs(gameplay, tg, textures);
            DrawHeightIndicators(gameplay, tg, textures);
        }
    }

    private void DrawTaps(GameplayService gameplay, int tg, TextureService textures)
    {
        _effect.Texture = textures.Get("tap");

        foreach (var tap in gameplay.GetVisibleTaps(tg))
        {
            float z = gameplay.GetNoteZ(tg, tap.Timing);
            float x = ArcFormula.LaneToWorldX(tap.Lane);
            float alpha = ArcFormula.CalculateFadeOutAlpha(z);
            float scale = ArcFormula.CalculateTapSizeScalar(z) * 0.25f;
            Color color = Color.White * alpha;

            DrawTexturedQuad(new Vector3(x, 0.15f, z), scale, scale * 0.3f, color);
        }
    }

    private void DrawHolds(GameplayService gameplay, int tg, TextureService textures)
    {
        _effect.Texture = textures.Get("hold");

        foreach (var hold in gameplay.GetVisibleHolds(tg))
        {
            float zStart = gameplay.GetNoteZ(tg, hold.Timing);
            float zEnd = gameplay.GetNoteZ(tg, hold.EndTiming);
            float x = ArcFormula.LaneToWorldX(hold.Lane);

            float clippedStart = Math.Clamp(zStart, -Values.TrackLengthForward, Values.TrackLengthBackward);
            float clippedEnd = Math.Clamp(zEnd, -Values.TrackLengthForward, Values.TrackLengthBackward);

            float halfWidth = Values.LaneWidth * 0.4f;
            float uvLen = Math.Abs(clippedEnd - clippedStart) * Values.HoldLengthScalar;
            Color color = new Color(255, 255, 255, (int)(Values.MaxHoldAlpha * 255));

            var verts = new VertexPositionColorTexture[]
            {
                new(new Vector3(x - halfWidth, 0.05f, clippedStart), color, new Vector2(0, 0)),
                new(new Vector3(x + halfWidth, 0.05f, clippedStart), color, new Vector2(1, 0)),
                new(new Vector3(x + halfWidth, 0.05f, clippedEnd), color, new Vector2(1, uvLen)),
                new(new Vector3(x - halfWidth, 0.05f, clippedEnd), color, new Vector2(0, uvLen)),
            };
            var indices = new short[] { 0, 1, 2, 0, 2, 3 };

            _device.SamplerStates[0] = SamplerState.LinearWrap;
            foreach (var pass in _effect.CurrentTechnique.Passes)
            {
                pass.Apply();
                _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
            }
            _device.SamplerStates[0] = SamplerState.LinearClamp;
        }
    }

    private void DrawArcs(GameplayService gameplay, int tg, TextureService textures)
    {
        _effect.Texture = textures.Get("arcBody");

        foreach (var arc in gameplay.GetVisibleArcs(tg))
        {
            Color baseColor = arc.IsTrace ? TraceColor
                : ArcColors[Math.Clamp(arc.Color, 0, ArcColors.Length - 1)];

            float offset = arc.IsTrace ? Values.TraceMeshOffset : Values.ArcMeshOffset;
            float maxAlpha = arc.IsTrace ? Values.TraceAlphaScalar : Values.MaxArcAlpha;

            int segments = Math.Max(1, (arc.EndTiming - arc.Timing) / 50);
            segments = Math.Min(segments, 200);

            var allVerts = new List<VertexPositionColorTexture>();
            var allIndices = new List<short>();

            for (int i = 0; i < segments; i++)
            {
                float t0 = (float)i / segments;
                float t1 = (float)(i + 1) / segments;

                int timing0 = arc.Timing + (int)((arc.EndTiming - arc.Timing) * t0);
                int timing1 = arc.Timing + (int)((arc.EndTiming - arc.Timing) * t1);

                float z0 = gameplay.GetNoteZ(tg, timing0);
                float z1 = gameplay.GetNoteZ(tg, timing1);

                if (!ArcFormula.WithinRenderRange(z0) && !ArcFormula.WithinRenderRange(z1)) continue;

                float ax0 = ArcFormula.X(arc.XStart, arc.XEnd, t0, arc.LineType);
                float ay0 = ArcFormula.Y(arc.YStart, arc.YEnd, t0, arc.LineType);
                float ax1 = ArcFormula.X(arc.XStart, arc.XEnd, t1, arc.LineType);
                float ay1 = ArcFormula.Y(arc.YStart, arc.YEnd, t1, arc.LineType);

                float wx0 = ArcFormula.ArcXToWorld(ax0);
                float wy0 = ArcFormula.ArcYToWorld(ay0);
                float wx1 = ArcFormula.ArcXToWorld(ax1);
                float wy1 = ArcFormula.ArcYToWorld(ay1);

                float alpha0 = ArcFormula.CalculateFadeOutAlpha(z0) * maxAlpha;
                float alpha1 = ArcFormula.CalculateFadeOutAlpha(z1) * maxAlpha;
                Color c0 = baseColor * alpha0;
                Color c1 = baseColor * alpha1;

                var start = new Vector3(wx0, wy0, z0);
                var end = new Vector3(wx1, wy1, z1);

                BuildDiamondSegment(allVerts, allIndices, start, end, offset, c0, c1);
            }

            if (allVerts.Count >= 3)
            {
                _device.SamplerStates[0] = SamplerState.LinearWrap;
                foreach (var pass in _effect.CurrentTechnique.Passes)
                {
                    pass.Apply();
                    _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList,
                        allVerts.ToArray(), 0, allVerts.Count,
                        allIndices.ToArray(), 0, allIndices.Count / 3);
                }
                _device.SamplerStates[0] = SamplerState.LinearClamp;
            }
        }
    }

    private void DrawArcShadows(GameplayService gameplay, int tg, TextureService textures)
    {
        _effect.Texture = textures.Get("shadow");

        foreach (var arc in gameplay.GetVisibleArcs(tg))
        {
            if (arc.IsTrace) continue;

            int segments = Math.Max(1, (arc.EndTiming - arc.Timing) / 100);
            segments = Math.Min(segments, 100);

            for (int i = 0; i <= segments; i++)
            {
                float t = (float)i / segments;
                int timing = arc.Timing + (int)((arc.EndTiming - arc.Timing) * t);
                float z = gameplay.GetNoteZ(tg, timing);
                if (!ArcFormula.WithinRenderRange(z)) continue;

                float ax = ArcFormula.X(arc.XStart, arc.XEnd, t, arc.LineType);
                float wx = ArcFormula.ArcXToWorld(ax);
                float alpha = ArcFormula.CalculateFadeOutAlpha(z) * 0.5f;

                DrawTexturedQuad(new Vector3(wx, 0.02f, z), 1.2f, 0.3f, ShadowColor * alpha);
            }
        }
    }

    private void DrawHeightIndicators(GameplayService gameplay, int tg, TextureService textures)
    {
        _effect.Texture = textures.Get("heightIndicator");

        foreach (var arc in gameplay.GetVisibleArcs(tg))
        {
            if (arc.IsTrace) continue;

            float z = gameplay.GetNoteZ(tg, arc.Timing);
            if (!ArcFormula.WithinRenderRange(z)) continue;

            float wx = ArcFormula.ArcXToWorld(arc.XStart);
            float wy = ArcFormula.ArcYToWorld(arc.YStart);
            float alpha = ArcFormula.CalculateFadeOutAlpha(z) * 0.7f;
            Color color = ArcColors[Math.Clamp(arc.Color, 0, ArcColors.Length - 1)] * alpha;

            // Vertical line from ground to arc start
            var verts = new VertexPositionColorTexture[]
            {
                new(new Vector3(wx - 0.15f, 0.01f, z), color, new Vector2(0, 1)),
                new(new Vector3(wx + 0.15f, 0.01f, z), color, new Vector2(1, 1)),
                new(new Vector3(wx + 0.15f, wy, z), color, new Vector2(1, 0)),
                new(new Vector3(wx - 0.15f, wy, z), color, new Vector2(0, 0)),
            };
            var indices = new short[] { 0, 1, 2, 0, 2, 3 };

            foreach (var pass in _effect.CurrentTechnique.Passes)
            {
                pass.Apply();
                _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
            }
        }
    }

    private static void BuildDiamondSegment(
        List<VertexPositionColorTexture> verts, List<short> indices,
        Vector3 start, Vector3 end, float offset, Color c0, Color c1)
    {
        short baseIdx = (short)verts.Count;

        // Diamond cross-section matching ArcMeshGenerator
        // Top center, right-bottom, left-bottom
        float halfOff = offset / 2f;

        // v0: top center start, v1: top center end
        // v2: right-bottom end, v3: right-bottom start
        // v4: left-bottom end, v5: left-bottom start
        verts.Add(new(start + new Vector3(0, halfOff, 0), c0, new Vector2(0, 0)));
        verts.Add(new(end + new Vector3(0, halfOff, 0), c1, new Vector2(1, 0)));
        verts.Add(new(end + new Vector3(offset, -halfOff, 0), c1, new Vector2(1, 1)));
        verts.Add(new(start + new Vector3(offset, -halfOff, 0), c0, new Vector2(0, 1)));
        verts.Add(new(end + new Vector3(-offset, -halfOff, 0), c1, new Vector2(1, 1)));
        verts.Add(new(start + new Vector3(-offset, -halfOff, 0), c0, new Vector2(0, 1)));

        // 4 triangles: right face (0,3,2)(0,2,1), left face (0,1,4)(0,4,5)
        indices.AddRange(new short[]
        {
            baseIdx, (short)(baseIdx + 3), (short)(baseIdx + 2),
            baseIdx, (short)(baseIdx + 2), (short)(baseIdx + 1),
            baseIdx, (short)(baseIdx + 1), (short)(baseIdx + 4),
            baseIdx, (short)(baseIdx + 4), (short)(baseIdx + 5),
        });
    }

    private void DrawTexturedQuad(Vector3 center, float width, float depth, Color color)
    {
        float hw = width / 2f;
        float hd = depth / 2f;
        var verts = new VertexPositionColorTexture[]
        {
            new(center + new Vector3(-hw, 0, -hd), color, new Vector2(0, 0)),
            new(center + new Vector3(hw, 0, -hd), color, new Vector2(1, 0)),
            new(center + new Vector3(hw, 0, hd), color, new Vector2(1, 1)),
            new(center + new Vector3(-hw, 0, hd), color, new Vector2(0, 1)),
        };
        var indices = new short[] { 0, 1, 2, 0, 2, 3 };

        foreach (var pass in _effect.CurrentTechnique.Passes)
        {
            pass.Apply();
            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
        }
    }
}

