using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
using BetterArc.Render;
using BetterArc.Input;
using BetterArc.Judgment;

namespace BetterArc;

public class BetterArcGame : Game
{
    private GraphicsDeviceManager _graphics;
    private SpriteBatch? _spriteBatch;
    private CameraService? _camera;
    private TextureService? _textures;
    private TrackRenderer? _track;
    private NoteRenderer? _notes;
    private Gameplay.GameplayService? _gameplay;
    private InputService? _input;
    private ScoreService? _score;
    private bool _autoPlay = true;
    private KeyboardState _prevKb;

    private readonly HashSet<int> _judgedTapTimings = new();
    private string _lastJudgment = "";
    private int _lastJudgmentTime;

    public BetterArcGame()
    {
        _graphics = new GraphicsDeviceManager(this);
        _graphics.PreferredBackBufferWidth = 1280;
        _graphics.PreferredBackBufferHeight = 720;
        Window.Title = "BetterArc v2";
        IsMouseVisible = true;
    }

    protected override void Initialize()
    {
        _camera = new CameraService();
        _track = new TrackRenderer(GraphicsDevice);
        _notes = new NoteRenderer(GraphicsDevice);
        _gameplay = new Gameplay.GameplayService();
        _input = new InputService();
        _score = new ScoreService();

        string chartPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "assets", "charts", "sayonarahatsukoi_ftr.aff");
        if (File.Exists(chartPath))
        {
            _gameplay.LoadChart(File.ReadAllText(chartPath));
            int totalNotes = _gameplay.Chart!.TimingGroups.Sum(
                tg => tg.Taps.Count + tg.Holds.Count + tg.Arcs.Count(a => !a.IsTrace));
            _score.SetNoteCount(totalNotes);
        }

        base.Initialize();
    }

    protected override void LoadContent()
    {
        _spriteBatch = new SpriteBatch(GraphicsDevice);
    }

    protected override void Update(GameTime gameTime)
    {
        var kb = Keyboard.GetState();
        _input!.Update();

        // Toggle auto-play with A key
        if (kb.IsKeyDown(Keys.A) && _prevKb.IsKeyUp(Keys.A))
            _autoPlay = !_autoPlay;

        // Timeline scrubbing
        int speed = kb.IsKeyDown(Keys.LeftShift) ? 100 : 20;
        if (kb.IsKeyDown(Keys.Right))
            _gameplay!.CurrentTiming += speed;
        if (kb.IsKeyDown(Keys.Left))
            _gameplay!.CurrentTiming = Math.Max(0, _gameplay.CurrentTiming - speed);
        if (kb.IsKeyDown(Keys.Space) && _prevKb.IsKeyUp(Keys.Space))
            _gameplay!.CurrentTiming = 0;

        // Judgment processing
        if (_gameplay!.Chart != null)
            ProcessJudgments();

        float aspect = GraphicsDevice.Viewport.AspectRatio;
        _camera!.Update(aspect);
        _prevKb = kb;

        base.Update(gameTime);
    }

    private void ProcessJudgments()
    {
        if (_gameplay?.Chart == null) return;

        for (int tg = 0; tg < _gameplay.Chart.TimingGroups.Count; tg++)
        {
            foreach (var tap in _gameplay.Chart.TimingGroups[tg].Taps)
            {
                int key = tap.Timing * 1000 + tg;
                if (_judgedTapTimings.Contains(key)) continue;

                int offset = _gameplay.CurrentTiming - tap.Timing;

                if (offset > Gameplay.Values.MissJudgeWindow)
                {
                    _judgedTapTimings.Add(key);
                    var result = JudgmentResult.MissLate;
                    _score!.ProcessResult(result);
                    ShowJudgment(result, offset);
                    continue;
                }

                if (_autoPlay && Math.Abs(offset) <= 5)
                {
                    _judgedTapTimings.Add(key);
                    _score!.ProcessResult(JudgmentResult.Max);
                    ShowJudgment(JudgmentResult.Max, 0);
                    continue;
                }

                if (!_autoPlay && JudgmentService.IsWithinWindow(offset))
                {
                    int lane = (int)Math.Round(tap.Lane);
                    if (_input!.IsLaneJustPressed(lane))
                    {
                        _judgedTapTimings.Add(key);
                        var result = JudgmentService.Judge(offset);
                        _score!.ProcessResult(result);
                        ShowJudgment(result, offset);
                    }
                }
            }
        }
    }

    private void ShowJudgment(JudgmentResult result, int offset)
    {
        string earlyLate = offset < 0 ? " EARLY" : offset > 0 ? " LATE" : "";
        _lastJudgment = result switch
        {
            JudgmentResult.Max => "PURE",
            JudgmentResult.PerfectEarly or JudgmentResult.PerfectLate => $"PURE{earlyLate}",
            JudgmentResult.GoodEarly or JudgmentResult.GoodLate => $"FAR{earlyLate}",
            _ => "LOST",
        };
        _lastJudgmentTime = _gameplay!.CurrentTiming;
    }

    protected override void Draw(GameTime gameTime)
    {
        GraphicsDevice.Clear(Color.Black);

        if (_camera != null && _track != null && _notes != null && _gameplay != null)
        {
            _track.Draw(_camera);
            _notes.Draw(_camera, _gameplay);
        }

        DrawHUD();
        base.Draw(gameTime);
    }

    private void DrawHUD()
    {
        if (_spriteBatch == null || _score == null || _gameplay == null) return;

        _spriteBatch.Begin();

        string mode = _autoPlay ? "[AUTO]" : "[D/F/J/K]";
        string hud = $"{mode}  Score: {_score.Score:N0}  Combo: {_score.CurrentCombo}  " +
                      $"Max:{_score.MaxCount} P:{_score.PerfectCount} G:{_score.GoodCount} M:{_score.MissCount}  " +
                      $"t={_gameplay.CurrentTiming}ms";

        // Draw judgment text (fade out after 500ms)
        if (_gameplay.CurrentTiming - _lastJudgmentTime < 500 && _lastJudgment.Length > 0)
        {
            hud += $"  [{_lastJudgment}]";
        }

        // Simple text rendering without SpriteFont - use Window title as HUD
        Window.Title = $"BetterArc v2 — {hud}";

        _spriteBatch.End();
    }

    public CameraService Camera => _camera!;
    public Gameplay.GameplayService GameplayService => _gameplay!;
}

